(5503057, 793764, 80887, '<td valign="top">Great shot! Do more of these. If you do this one again, try one with the stem protruding up into the black background.</td>', 'Great shot! Do more of these. If you do this one again, try one with the stem protruding up into the black background.', '2009-05-27 23:31:15.000000', NULL, 1),
(5503064, 792907, 80887, '<td valign="top">Great shot. I''d like to see this hanging in a well appointed kitchen. Preferably mine, if I had a well appointed kitchen.</td>', 'Great shot. I''d like to see this hanging in a well appointed kitchen. Preferably mine, if I had a well appointed kitchen.', '2009-05-27 23:34:34.000000', NULL, 1),
(5503065, 793754, 80887, '<td valign="top">C''est magnifique!</td>', 'C''est magnifique!', '2009-05-27 23:35:17.000000', NULL, 1),
(5503066, 793326, 80887, '<td valign="top">Looks good enough to eat!</td>', 'Looks good enough to eat!', '2009-05-27 23:35:44.000000', NULL, 1),
(5503072, 793816, 80887, '<td valign="top">Nicely done. Turn the Suave bottle around so we can''t see the words. (If there are words on the other side, too, try wiping them off with some nail polish remover.) The piece of fruit (or whatever that is) has lots details. Try shading it somehow.</td>', 'Nicely done. Turn the Suave bottle around so we can''t see the words. (If there are words on the other side, too, try wiping them off with some nail polish remover.) The piece of fruit (or whatever that is) has lots details. Try shading it somehow.', '2009-05-27 23:37:43.000000', NULL, 1),
(5503073, 793246, 80887, '<td valign="top">Wonderful. I can feel what those hands are feeling.</td>', 'Wonderful. I can feel what those hands are feeling.', '2009-05-27 23:38:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5503108, 793911, 81362, '<td valign="top">The stack of rocks conveys a sense of zen. I''m wondering how you trained the snail. Softer light might have enhanced a little, but overall very well done. 8.</td>', 'The stack of rocks conveys a sense of zen. I''m wondering how you trained the snail. Softer light might have enhanced a little, but overall very well done. 8.', '2009-05-28 00:08:25.000000', NULL, 1),
(5503111, 793608, 81362, '<td valign="top">Classic art object with ties set in just the right combination of casual and posed. Excellent leading lines, and wise decision to process black and white.</td>', 'Classic art object with ties set in just the right combination of casual and posed. Excellent leading lines, and wise decision to process black and white.', '2009-05-28 00:10:47.000000', NULL, 1),
(5503115, 793907, 81362, '<td valign="top">Conveys a sense of quiet and beauty very well. Not sure about including the reflection of the large petal, but that is a vaild alternative. I like your inclusion of a horizontal stem.</td>', 'Conveys a sense of quiet and beauty very well. Not sure about including the reflection of the large petal, but that is a vaild alternative. I like your inclusion of a horizontal stem.', '2009-05-28 00:13:40.000000', NULL, 1),
(5503117, 793754, 81362, '<td valign="top">Deceptive simplicity, with light on the cups just right to show off their clean lines. Ideal execution might have used a slightly shallower depth of field to decrease background texture (or maybe have it a bit further away). 8 nevertheless.</td>', 'Deceptive simplicity, with light on the cups just right to show off their clean lines. Ideal execution might have used a slightly shallower depth of field to decrease background texture (or maybe have it a bit further away). 8 nevertheless.', '2009-05-28 00:15:45.000000', NULL, 1),
(5503120, 792737, 81362, '<td valign="top">Wonderful combination of lime green and reds. Spotlight from above works well. The central light position in front resulted in good shadow position but also included some distracting glare. Wondering if light from two sides might have decreased that. 7.</td>', 'Wonderful combination of lime green and reds. Spotlight from above works well. The central light position in front resulted in good shadow position but also included some distracting glare. Wondering if light from two sides might have decreased that. 7.', '2009-05-28 00:18:54.000000', NULL, 1),
(5503122, 792907, 81362, '<td valign="top">Ready to frame and hang in a kitchen store. Side lighting makes me think of morning harvest. Nice balance of illumination on the other side too, perhaps using a reflector?</td>', 'Ready to frame and hang in a kitchen store. Side lighting makes me think of morning harvest. Nice balance of illumination on the other side too, perhaps using a reflector?', '2009-05-28 00:20:41.000000', NULL, 1),
(5503161, 793906, 97611, '<td valign="top">Gr8 use of colors.. Excellent work.... 10 from me....</td>', 'Gr8 use of colors.. Excellent work.... 10 from me....', '2009-05-28 01:32:27.000000', NULL, 1),
(5503162, 793931, 97611, '<td valign="top">Amazing... Expectin more from you</td>', 'Amazing... Expectin more from you', '2009-05-28 01:32:51.000000', NULL, 1),
(5503187, 793764, 31637, '<td valign="top">Perfect use of frame and lighting. 8</td>', 'Perfect use of frame and lighting. 8', '2009-05-28 02:11:21.000000', NULL, 1),
(5503189, 793885, 31637, '<td valign="top">What about the outlaw Josie Wales? eh..fiction I know, quite the collection of books there, it''s a very good abstract type image.</td>', 'What about the outlaw Josie Wales? eh..fiction I know, quite the collection of books there, it''s a very good abstract type image.', '2009-05-28 02:14:47.000000', NULL, 1),
