(5503195, 792838, 105764, '<td valign="top">Most imaginative I have seen yet!  Bravo!<br/>If it was intigrated into a "still life" scene it would have been a ten.</td>', 'Most imaginative I have seen yet!  Bravo!If it was intigrated into a "still life" scene it would have been a ten.', '2009-05-28 02:21:23.000000', NULL, 1),
(5503206, 793845, 14867, '<td valign="top">Among the few being a real still life, this is also showing creativity. 9.</td>', 'Among the few being a real still life, this is also showing creativity. 9.', '2009-05-28 02:59:46.000000', NULL, 1),
(5503207, 793787, 41337, '<td valign="top">I kinda like this. Unassuming yet effective.</td>', 'I kinda like this. Unassuming yet effective.', '2009-05-28 03:01:11.000000', NULL, 1),
