(5503909, 793958, 105171, '<td valign="top">Nice color blend.  I would have preferred the lighting on a different angle.</td>', 'Nice color blend.  I would have preferred the lighting on a different angle.', '2009-05-28 15:50:42.000000', NULL, 1),
(5503910, 793953, 105171, '<td valign="top">Seems to lack focus.</td>', 'Seems to lack focus.', '2009-05-28 15:52:27.000000', NULL, 1),
