(5508403, 793487, 70128, '<td valign="top">I love this picture, but I don''t see where this fits the challenge. Not rating it.</td>', 'I love this picture, but I don''t see where this fits the challenge. Not rating it.', '2009-06-01 14:18:56.000000', NULL, 1),
(5508406, 793936, 70128, '<td valign="top">You almost look like Ringo Starr dressed like that, and the beard! LOL very nice shot!</td>', 'You almost look like Ringo Starr dressed like that, and the beard! LOL very nice shot!', '2009-06-01 14:19:56.000000', NULL, 1),
(5508411, 793227, 83313, '<td valign="top">Not what I consider a still-life. Maybe my understanding of it is wrong.</td>', 'Not what I consider a still-life. Maybe my understanding of it is wrong.', '2009-06-01 14:22:55.000000', NULL, 1),
(5508415, 793966, 83313, '<td valign="top">Watch your JPG compression. Lots of black meant this compressed well, but at a file size of only 50k, you had a lot more overhead and may have been able to squeeze some more quality out of this.</td>', 'Watch your JPG compression. Lots of black meant this compressed well, but at a file size of only 50k, you had a lot more overhead and may have been able to squeeze some more quality out of this.', '2009-06-01 14:25:31.000000', NULL, 1),
(5508418, 792952, 83313, '<td valign="top">I will not be swayed by bright colors...  I will not be swayed by bright colors...  I will not be swayed by bright colors... Oh heck!</td>', 'I will not be swayed by bright colors...  I will not be swayed by bright colors...  I will not be swayed by bright colors... Oh heck!', '2009-06-01 14:26:37.000000', NULL, 1),
(5508424, 793942, 83313, '<td valign="top">She''s a hottie, that''s for sure!</td>', 'She''s a hottie, that''s for sure!', '2009-06-01 14:27:58.000000', NULL, 1),
(5508430, 792625, 83313, '<td valign="top">Not my idea of still life. I could be mistaken about the definition.</td>', 'Not my idea of still life. I could be mistaken about the definition.', '2009-06-01 14:29:34.000000', NULL, 1),
(5508440, 793057, 83313, '<td valign="top">A very dim, flat looking image. I popped this into my image editor and found that a levels adjustment, followed by curves, did wonders for it. The histogram was totally flat on the right hand side. Still a lot of blotchiness in the background, though. From my own personal experience, I don''t think that is ISO grain, but rather the uneven pattern of your background paper. Hard to fix that in basic editing. Best option for that is to experiment with lighting to try and minimize the appearance. Or find different background material.</td>', 'A very dim, flat looking image. I popped this into my image editor and found that a levels adjustment, followed by curves, did wonders for it. The histogram was totally flat on the right hand side. Still a lot of blotchiness in the background, though. From my own personal experience, I don''t think that is ISO grain, but rather the uneven pattern of your background paper. Hard to fix that in basic editing. Best option for that is to experiment with lighting to try and minimize the appearance. Or find different background material.', '2009-06-01 14:35:54.000000', NULL, 1),
(5508442, 793604, 83313, '<td valign="top">I''ll see this one near the top.</td>', 'I''ll see this one near the top.', '2009-06-01 14:36:59.000000', NULL, 1),
(5508445, 793099, 83313, '<td valign="top">Traditional still life subjects, nicely done. The blurriness of the ones in the background looks a bit odd, however.</td>', 'Traditional still life subjects, nicely done. The blurriness of the ones in the background looks a bit odd, however.', '2009-06-01 14:38:15.000000', NULL, 1),
(5508447, 793321, 83313, '<td valign="top">Those are some strange looking peaches. I''ll be you had to hunt through the bin at the store to find them.</td>', 'Those are some strange looking peaches. I''ll be you had to hunt through the bin at the store to find them.', '2009-06-01 14:39:34.000000', NULL, 1),
(5508449, 793101, 83313, '<td valign="top">I know I''ve seen this shot before. I think this is a Roz pic, or maybe Jutilda.</td>', 'I know I''ve seen this shot before. I think this is a Roz pic, or maybe Jutilda.', '2009-06-01 14:40:41.000000', NULL, 1),
(5508521, 793973, 18403, '<td valign="top">Too dark, but nice subject.</td>', 'Too dark, but nice subject.', '2009-06-01 15:23:01.000000', NULL, 1),
(5508531, 793930, 18403, '<td valign="top">Many have submitted photos of unconventional still life subjects, but it is hard to beat a well done traditional vase and flowers.  This one is exceptional. 10</td>', 'Many have submitted photos of unconventional still life subjects, but it is hard to beat a well done traditional vase and flowers.  This one is exceptional. 10', '2009-06-01 15:26:49.000000', NULL, 1),
